import{z as i,x as d,o as A,c,q as t,j as o,D as n,d as e,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"AEAD 与 GCM 内部","description":"","frontmatter":{"title":"AEAD 与 GCM 内部","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aead-gcm-internals.md","filePath":"cs/aead-gcm-internals.md","lastUpdated":1791063341000}'),p={name:"cs/aead-gcm-internals.md"};function B(D,a,C,h,m,T){const r=d("Mermaid");return A(),c("div",null,[a[2]||(a[2]=t('<h1 id="aead-与-gcm-内部" tabindex="-1">AEAD 与 GCM 内部 <a class="header-anchor" href="#aead-与-gcm-内部" aria-label="Permalink to &quot;AEAD 与 GCM 内部&quot;">​</a></h1><div class="epigraph"><p>AEAD 一次调用同时给出保密与完整性。GCM 用 CTR 加密，用有限域上的 GHASH 吃密文与附加数据；标签错了就该丢整条消息。</p><footer>—— McGrew and Viega, The Galois/Counter Mode；NIST SP 800-38D</footer></div><p>上一课<a href="/cs/chacha20">ChaCha20</a>给出软件密钥流。主干<a href="/cs/block-modes">分组模式</a>已把 GCM 当 AEAD 名字。缺口是<strong>内部</strong>：CTR 与 GHASH 如何咬合，附加数据（AAD）为何不加密却进标签。<a href="/cs/mac-signature">MAC 与签名</a>的 Encrypt-then-MAC 在此收成单一原语。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只加密的 CBC 留下主动篡改。GCM：密钥流来自 AES-CTR（或等价），认证来自 $ \\mathrm{GF}(2^{128}) $ 上的多项式求值 GHASH，最后再加密得到标签。AAD 让头部明文仍被认证。缺口是理解「一次 nonce、一块标签」的合同，不是再背套件名。</p><h3 id="标签失败即拒绝" tabindex="-1">标签失败即拒绝 <a class="header-anchor" href="#标签失败即拒绝" aria-label="Permalink to &quot;标签失败即拒绝&quot;">​</a></h3><p>解密先验标签；失败则不释放明文。把失败当「再试试填充」会重开预言机——下一课。</p><p><span class="marginnote">SP 800-38D 限制同一密钥下 nonce 不得重复。96 比特 nonce 最常见。GHASH 不是抗碰撞哈希；它是带密钥的通用哈希，安全靠密钥保密与 nonce 唯一。</span></p><p><span class="marginnote">术语翻译：AAD（附加数据）就是用「不加密、但进标签」的手段来做「头部可读却不可篡改」的事——比如 TLS 的记录头必须明文传输让网络设备看懂，又不许中间人改一个比特：改了，标签对不上，整条记录作废。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：J0 从 nonce 来，CTR 加密块，GHASH 扫 AAD 与密文，再与 E(K,J0) 混合成标签。对照 ChaCha20-Poly1305：同一 AEAD 形状，多项式不同。指出 TLS 1.3 只保留 AEAD。</p>',12)),(A(),o(l,null,{default:n(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22nonce%22%5D%20--%3E%20CTR%5B%22AES-CTR%20%E5%AF%86%E9%92%A5%E6%B5%81%22%5D%0A%20%20PT%5B%22%E6%98%8E%E6%96%87%22%5D%20--%3E%20CTR%0A%20%20CTR%20--%3E%20CT%5B%22%E5%AF%86%E6%96%87%22%5D%0A%20%20AAD%5B%22%E9%99%84%E5%8A%A0%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20GH%5B%22GHASH%22%5D%0A%20%20CT%20--%3E%20GH%0A%20%20GH%20--%3E%20T%5B%22%E8%AE%A4%E8%AF%81%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("AEAD 把"),E("a",{href:"/cs/cia-triad"},"CIA"),e("的 C 与 I 绑到同一密钥与同一 nonce。主动改密文或 AAD 会使标签失败。它仍假设密钥未泄漏、实现常数时间、nonce 不重复。公钥与身份不在本课。")],-1)),a[5]||(a[5]=E("p",null,"方法一节的图回答「发送方怎么把保密与认证拧在一起」，下面这张回答另一个问题：接收方收到一条消息后，标签校验与解密的先后与分支。",-1)),(A(),o(l,null,{default:n(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%94%B6%E5%88%B0%3A%20%E5%AF%86%E6%96%87%20%2B%20AAD%20%2B%20%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20GH%5B%22%E7%94%A8%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%E4%B8%8E%20nonce%20%E9%87%8D%E7%AE%97%20GHASH%22%5D%0A%20%20GH%20--%3E%20MIX%5B%22%E4%B8%8E%20E(K%2C%20J0)%20%E6%B7%B7%E5%90%88%E5%BE%97%E5%80%99%E9%80%89%E6%A0%87%E7%AD%BE%22%5D%0A%20%20MIX%20--%3E%20CMP%7B%22%E4%B8%8E%E6%94%B6%E5%88%B0%E7%9A%84%E6%A0%87%E7%AD%BE%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20CMP%20--%20%22%E5%90%A6%22%20--%3E%20REJ%5B%22%E6%95%B4%E6%9D%A1%E4%B8%A2%E5%BC%83%2C%20%E4%B8%8D%E9%87%8A%E6%94%BE%E4%BB%BB%E4%BD%95%E6%98%8E%E6%96%87%22%5D%0A%20%20CMP%20--%20%22%E6%98%AF%22%20--%3E%20DEC%5B%22AES-CTR%3A%20%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%E6%B5%81%E5%BC%82%E6%88%96%E8%BF%98%E5%8E%9F%E6%98%8E%E6%96%87%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">数字实例：128 比特标签意味着攻击者盲改一次密文蒙混过关的概率约 \\(2^{-128}\\approx 3\\times 10^{-39}\\)——比连中十几次彩票还稀罕得多。但nonce 只有 96 比特且不得重复：NIST 建议同一密钥加密次数不超过 \\(2^{32}\\)，靠生日界保证 nonce 不撞。</span></p><p><span class="marginnote">常见误区：初学者容易把「标签失败」当成另一种「解密出错」去细究原因、返回不同报错——这条差异路径正是下一课填充预言机攻击的原料。正确动作只有一种：标签不对，整条丢掉，错误信息与别的一模一样。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GHASH 的全部域算术作业，不给 nonce 复用下的密钥恢复步骤。下一课专收 <strong>nonce 误用与重放</strong>：合同一旦破，GCM 的证明作废。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流密码与分组密码都要 AEAD 包装。</li><li>GCM：CTR 保密，GHASH 认证，AAD 进标签。</li><li>标签失败则丢消息；不要当填充预言。</li><li>nonce 唯一是下一课的主缺口。</li><li>出处：McGrew and Viega；NIST SP 800-38D；RFC 5116 AEAD 接口。</li></ul>',6))])}const G=i(p,[["render",B]]);export{u as __pageData,G as default};
